SELECT a.application_id AS applicationId, a.user_id AS userId, a.reason AS reason, a.status AS status, a.reviewer_id AS reviewerId, a.review_comment AS reviewComment, a.create_time AS createTime, a.review_time AS reviewTime, u.username AS username, u.phone AS phone, r.username AS reviewerName FROM seller_application a LEFT JOIN user u ON a.user_id = u.user_id LEFT JOIN user r ON a.reviewer_id = r.user_id
AND a.status = #{status}
ORDER BY a.application_id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM seller_application



        AND status = #{status}
